package com.riverasmotor.harvisa01;
import android.app.*;import android.os.*;import android.content.*;import android.content.pm.PackageManager;import android.media.AudioManager;import android.bluetooth.BluetoothAdapter;import android.speech.tts.TextToSpeech;import android.view.View;import android.widget.*;import org.json.*;import org.vosk.*;import org.vosk.android.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;
public class MainActivity extends Activity implements TextToSpeech.OnInitListener,RecognitionListener{
 EditText baseUrl,token,message;TextView status,chat,orb,processLog;ScrollView scroll,processScroll;LinearLayout settings,textPanel;View voiceSpace;Button mode;CoreVisualizerView coreVisual;TextToSpeech tts;AudioManager audio;Handler retry=new Handler();boolean stopped=false,textMode=false;Model voskModel;Recognizer voskRecognizer;SpeechService speechService;
 @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);baseUrl=findViewById(R.id.baseUrl);token=findViewById(R.id.token);message=findViewById(R.id.message);status=findViewById(R.id.status);chat=findViewById(R.id.chat);orb=findViewById(R.id.orb);scroll=findViewById(R.id.scroll);settings=findViewById(R.id.settings);coreVisual=findViewById(R.id.coreVisual);processLog=findViewById(R.id.processLog);processScroll=findViewById(R.id.processScroll);textPanel=findViewById(R.id.textPanel);voiceSpace=findViewById(R.id.voiceSpace);mode=findViewById(R.id.mode);SharedPreferences p=getSharedPreferences("harvis",0);baseUrl.setText(p.getString("url","http://192.168.0.57:8765"));token.setText(p.getString("token",""));tts=new TextToSpeech(this,this);audio=(AudioManager)getSystemService(AUDIO_SERVICE);initVosk();findViewById(R.id.config).setOnClickListener(v->settings.setVisibility(settings.getVisibility()==View.VISIBLE?View.GONE:View.VISIBLE));findViewById(R.id.connect).setOnClickListener(v->{stopped=false;health(true);settings.setVisibility(View.GONE);});findViewById(R.id.send).setOnClickListener(v->send());findViewById(R.id.mic).setOnClickListener(v->listen());findViewById(R.id.audio).setOnClickListener(v->routeBluetooth(true));findViewById(R.id.stop).setOnClickListener(v->{stopped=true;stopListening();stopService(new Intent(this,HarvisVoiceService.class));if(tts!=null)tts.stop();stopBluetooth();state("CORE // PAUSA","PAUSA");proc("Segundo plano detenido");});mode.setOnClickListener(v->toggleMode());findViewById(R.id.process).setOnClickListener(v->processScroll.setVisibility(processScroll.getVisibility()==View.VISIBLE?View.GONE:View.VISIBLE));health(true);}
 void toggleMode(){textMode=!textMode;textPanel.setVisibility(textMode?View.VISIBLE:View.GONE);voiceSpace.setVisibility(textMode?View.GONE:View.VISIBLE);mode.setText(textMode?"MODO VOZ":"MODO TEXTO");if(textMode)bottom();}
 void proc(String s){ui(()->{processLog.append("\n"+s);processScroll.post(()->processScroll.fullScroll(ScrollView.FOCUS_DOWN));});}
 void initVosk(){state("VOSK // CARGANDO","CARGANDO");proc("Cargando Vosk");StorageService.unpack(this,"model-es","model-es",m->{voskModel=m;state("VOSK // LISTO","LISTO");proc("Vosk listo");},e->{state("VOSK // ERROR","ERROR");append("SYSTEM // Vosk: "+e.getMessage()+"\n\n");});}
 @Override public void onInit(int s){if(s==TextToSpeech.SUCCESS){tts.setLanguage(new Locale("es","AR"));tts.setSpeechRate(1.08f);tts.setPitch(1f);}}
 String cleanToken(){return token.getText().toString().replace("\u200B","").replace("\u200C","").replace("\u200D","").replace("\uFEFF","").replaceAll("\\s+","").trim();}
 void save(){String t=cleanToken();token.setText(t);getSharedPreferences("harvis",0).edit().putString("url",baseUrl.getText().toString().trim()).putString("token",t).commit();}
 HttpURLConnection conn(String path,String method)throws Exception{String root=baseUrl.getText().toString().trim().replaceAll("/+$","");if(root.isEmpty())throw new Exception("Falta URL del Core");HttpURLConnection c=(HttpURLConnection)new URL(root+path).openConnection();c.setConnectTimeout(4500);c.setReadTimeout(120000);c.setRequestMethod(method);c.setRequestProperty("Content-Type","application/json; charset=utf-8");String t=cleanToken();if(!t.isEmpty()){c.setRequestProperty("Authorization","Bearer "+t);c.setRequestProperty("X-HARVIS-Token",t);}return c;}
 void health(boolean load){save();state("CORE // CONECTANDO","CONECTANDO");proc("Conectando al Core");new Thread(()->{try{HttpURLConnection c=conn("/health","GET");String s=read(c);int code=c.getResponseCode();if(code<400){ui(()->{stopped=false;state("MARK I • NÚCLEO ONLINE","EN ESPERA");routeBluetooth(false);proc("Core online");});if(load)bootstrap();}else if(code==401)fail("HTTP 401 // TOKEN RECHAZADO // longitud="+cleanToken().length());else fail("HTTP "+code+" "+s);}catch(Exception e){fail(e.getMessage());}}).start();}
 void bootstrap(){new Thread(()->{try{HttpURLConnection c=conn("/v1/bootstrap","GET");String s=read(c);if(c.getResponseCode()>=400)return;JSONArray h=new JSONObject(s).optJSONArray("history");StringBuilder b=new StringBuilder();if(h!=null)for(int i=Math.max(0,h.length()-14);i<h.length();i++){JSONObject x=h.optJSONObject(i);if(x!=null)b.append("user".equals(x.optString("role"))?"VOS  // ":"HARVIS // ").append(x.optString("content",x.optString("text",""))).append("\n\n");}ui(()->{chat.setText(b.toString());bottom();proc("Contexto cargado");});}catch(Exception ignored){}}).start();}
 String speechOnly(String s){StringBuilder b=new StringBuilder();boolean src=false;for(String line:s.split("\\r?\\n")){String t=line.trim(),u=t.toUpperCase(Locale.ROOT);if(u.startsWith("FUENTE")||u.startsWith("SOURCE")||u.startsWith("REFERENCIA")||u.startsWith("BIBLIOGRAF")||u.startsWith("CITACIÓN")||u.startsWith("CITACION")){src=true;continue;}if(src){if(t.isEmpty())src=false;else continue;}t=t.replaceAll("https?://\\S+|www\\.\\S+","").replaceAll("[`*_#~|<>\\[\\]{}]+"," ").replaceAll("/{2,}|\\\\{2,}"," ").replaceAll("[-=]{2,}"," ").replaceAll("\\s+"," ").trim();if(!t.isEmpty())b.append(t).append(". ");}return b.toString().trim();}
 void send(){String m=message.getText().toString().trim();if(m.isEmpty()||stopped)return;save();message.setText("");append("VOS  // "+m+"\n\n");state("CORE // PROCESANDO","PROCESANDO");proc("Consulta enviada");new Thread(()->{try{JSONObject j=new JSONObject();j.put("message",m);j.put("text",m);j.put("device","android-a01-mark1-vosk");HttpURLConnection c=conn("/v1/chat","POST");c.setDoOutput(true);try(OutputStream o=c.getOutputStream()){o.write(j.toString().getBytes(StandardCharsets.UTF_8));}String raw=read(c);if(c.getResponseCode()>=400)throw new Exception("HTTP "+c.getResponseCode()+" "+raw);JSONObject r=new JSONObject(raw);String a=r.optString("answer",r.optString("response",r.optString("text","")));if(a.trim().isEmpty())a=raw;final String ans=a;ui(()->{append("HARVIS // "+ans+"\n\n");proc("Respuesta recibida");state("AUDIO // HABLANDO","HABLANDO");String spoken=speechOnly(ans);if(tts!=null&&!spoken.isEmpty())tts.speak(spoken,TextToSpeech.QUEUE_FLUSH,null,"harvis");});}catch(Exception e){fail(e.getMessage());}}).start();}
 void listen(){if(stopped)stopped=false;if(Build.VERSION.SDK_INT>=23&&checkSelfPermission("android.permission.RECORD_AUDIO")!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{"android.permission.RECORD_AUDIO"},7);return;}if(voskModel==null){Toast.makeText(this,"Vosk todavía está cargando",Toast.LENGTH_SHORT).show();return;}stopListening();try{voskRecognizer=new Recognizer(voskModel,16000f);speechService=new SpeechService(voskRecognizer,16000f);speechService.startListening(this);state("VOSK // ESCUCHANDO","ESCUCHANDO");proc("Escuchando voz");}catch(Exception e){append("SYSTEM // Vosk audio: "+e.getMessage()+"\n");}}
 void stopListening(){if(speechService!=null){speechService.stop();speechService.shutdown();speechService=null;}if(voskRecognizer!=null){voskRecognizer.close();voskRecognizer=null;}}
 @Override public void onResult(String h){try{String text=new JSONObject(h).optString("text","").trim();if(!text.isEmpty()){stopListening();message.setText(text);proc("Voz reconocida");send();}}catch(Exception e){append("SYSTEM // Vosk resultado inválido\n");}}@Override public void onFinalResult(String h){if(speechService!=null)onResult(h);}@Override public void onPartialResult(String h){}@Override public void onError(Exception e){stopListening();state("MARK I • NÚCLEO ONLINE","EN ESPERA");}@Override public void onTimeout(){stopListening();}
 void routeBluetooth(boolean announce){try{BluetoothAdapter b=BluetoothAdapter.getDefaultAdapter();boolean bt=b!=null&&b.isEnabled();if(bt){audio.setMode(AudioManager.MODE_IN_COMMUNICATION);audio.startBluetoothSco();audio.setBluetoothScoOn(true);}((Button)findViewById(R.id.audio)).setText(bt?"BT AUDIO":"AUDIO");if(announce)Toast.makeText(this,bt?"Bluetooth de audio solicitado":"Bluetooth no activo",Toast.LENGTH_SHORT).show();}catch(Exception ignored){}}
 void stopBluetooth(){try{audio.setBluetoothScoOn(false);audio.stopBluetoothSco();audio.setMode(AudioManager.MODE_NORMAL);}catch(Exception ignored){}}
 String read(HttpURLConnection c)throws Exception{int code=c.getResponseCode();InputStream in=code<400?c.getInputStream():c.getErrorStream();if(in==null)return "";BufferedReader r=new BufferedReader(new InputStreamReader(in,StandardCharsets.UTF_8));StringBuilder s=new StringBuilder();String l;while((l=r.readLine())!=null)s.append(l);return s.toString();}
 void state(String s,String o){ui(()->{status.setText(s);orb.setText(o);if(coreVisual!=null)coreVisual.setMode(o);});}void append(String s){ui(()->{chat.append(s);bottom();});}void bottom(){scroll.post(()->scroll.fullScroll(ScrollView.FOCUS_DOWN));}void ui(Runnable r){runOnUiThread(r);}void fail(String e){ui(()->{state("CORE // SIN ENLACE","SIN ENLACE");append("SYSTEM // "+e+"\n\n");proc("Sin enlace: "+e);if(!stopped)retry.postDelayed(()->health(false),5000);});}
 @Override public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==7&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED)listen();}
 @Override protected void onResume(){super.onResume();stopService(new Intent(this,HarvisVoiceService.class));if(baseUrl!=null&&!stopped)health(false);}
 @Override protected void onStop(){super.onStop();if(!stopped&&Build.VERSION.SDK_INT>=23&&checkSelfPermission("android.permission.RECORD_AUDIO")==PackageManager.PERMISSION_GRANTED){stopListening();Intent i=new Intent(this,HarvisVoiceService.class);if(Build.VERSION.SDK_INT>=26)startForegroundService(i);else startService(i);}}
 @Override protected void onDestroy(){retry.removeCallbacksAndMessages(null);stopListening();stopBluetooth();if(tts!=null){tts.stop();tts.shutdown();}if(voskModel!=null)voskModel.close();super.onDestroy();}
}